"""Build and freeze the manual ground-truth dataset for the 5 blind held-out documents (Stage 4.4 Part A).

IMPORTANT METHODOLOGY CONSTRAINT:
This ground-truth dataset is constructed and frozen BEFORE developing `src/requirement_extraction/generic_parser.py`.
Every ground-truth annotation is verified against the verbatim raw text (`raw_text[source_char_start:source_char_end] == evidence_text`).
"""

from __future__ import annotations

import hashlib
import json
import re
from pathlib import Path
from typing import Any

PROJECT_ROOT = Path(__file__).resolve().parents[1]
RAW_TXT_DIR = PROJECT_ROOT / "data" / "raw" / "txt"
PROCESSED_DIR = PROJECT_ROOT / "data" / "processed"
OUTPUT_PATH = PROCESSED_DIR / "held_out_ground_truth.json"


def _compute_page_number(raw_text: str, char_pos: int) -> int:
    """Compute 1-based page number using triple-newline page breaks (`\\n\\n\\n`)."""
    prefix = raw_text[: max(0, char_pos)]
    return prefix.count("\n\n\n") + 1


def _pattern_from_phrase(phrase: str) -> str:
    cleaned = phrase.replace("\u200b", " ")
    tokens = re.findall(r"\w+|[^\w\s]", cleaned, flags=re.UNICODE)
    return r"[\s\u200b]*".join(re.escape(tok) for tok in tokens)


def _find_exact_span(raw_text: str, snippet: str, start_from: int = 0) -> tuple[int, int, str]:
    """Locate exact snippet in raw_text starting from start_from and verify verbatim match."""
    idx = raw_text.find(snippet, start_from)
    if idx != -1:
        end_idx = idx + len(snippet)
        return idx, end_idx, raw_text[idx:end_idx]

    sub = raw_text[start_from:]
    words = snippet.split()
    start_phrase = " ".join(words[: min(8, len(words))])
    end_phrase = " ".join(words[max(0, len(words) - 8) :])

    m_start = re.search(_pattern_from_phrase(start_phrase), sub, flags=re.IGNORECASE)
    if not m_start:
        raise ValueError(f"Start phrase not found from {start_from}: {start_phrase!r}")

    s_rel = m_start.start()
    m_end = re.search(_pattern_from_phrase(end_phrase), sub[s_rel:], flags=re.IGNORECASE)
    if not m_end:
        raise ValueError(f"End phrase not found after {start_from + s_rel}: {end_phrase!r}")

    s = start_from + s_rel
    e = start_from + s_rel + m_end.end()
    assert raw_text[s:e]
    return s, e, raw_text[s:e]


def _make_gt_record(
    *,
    gt_id: str,
    document_id: str,
    branch_unit_id: str,
    raw_text: str,
    snippet: str,
    start_from: int = 0,
    requirement_category: str,
    requirement_subcategory: str,
    requirement_name: str,
    requirement_description: str,
    source_section: str,
    statement_nature: str = "mandatory_requirement",
    evidence_type: str = "explicit_rule",
    canonical_topics: list[str] | None = None,
) -> dict[str, Any]:
    s, e, ev = _find_exact_span(raw_text, snippet, start_from=start_from)
    page = _compute_page_number(raw_text, s)
    return {
        "gt_id": gt_id,
        "document_id": document_id,
        "branch_unit_id": branch_unit_id,
        "requirement_category": requirement_category,
        "requirement_subcategory": requirement_subcategory,
        "requirement_name": requirement_name,
        "requirement_description": requirement_description,
        "evidence_text": ev,
        "source_char_start": s,
        "source_char_end": e,
        "source_page": page,
        "source_section": source_section,
        "statement_nature": statement_nature,
        "evidence_type": evidence_type,
        "canonical_topics": canonical_topics or [],
    }


